<script setup lang="ts">
import { ref } from 'vue'
import { account, authEnabled, logout } from '@/composables/useAccount'
import { apiRequest } from '@/services/http'
const link=ref(''),error=ref(''),busy=ref(false),currentPassword=ref(''),newPassword=ref(''),success=ref('')
async function password(){busy.value=true;error.value='';success.value='';try{await apiRequest('auth/password',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({current_password:currentPassword.value,new_password:newPassword.value})});currentPassword.value='';newPassword.value='';success.value='Contraseña actualizada. Las otras sesiones se cerraron.'}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function invite(){busy.value=true;error.value='';try{const result=await apiRequest<{invitation:string}>('auth/invitations',{method:'POST'});link.value=`${location.origin}/#/registro?invitacion=${encodeURIComponent(result.invitation)}`}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
async function exit(){try{await logout()}catch(e){error.value=(e as Error).message}}
</script>
<template><section v-if="authEnabled" class="account-settings"><h2>Tu cuenta</h2><p>{{account?.username}}</p><form @submit.prevent="password"><h3>Cambiar contraseña</h3><label>Contraseña actual<input v-model="currentPassword" type="password" autocomplete="current-password" minlength="12" maxlength="128" required /></label><label>Nueva contraseña<input v-model="newPassword" type="password" autocomplete="new-password" minlength="12" maxlength="128" required /></label><button class="outline" :disabled="busy">Actualizar contraseña</button><p v-if="success" role="status">{{success}}</p></form><button type="button" class="outline" @click="exit">Cerrar sesión</button><div v-if="account?.admin"><h3>Invitar a un amigo</h3><p>Cada enlace permite crear una cuenta y vence en siete días. Compártelo solo con la persona invitada.</p><button type="button" class="primary" :disabled="busy" @click="invite">Crear invitación</button><label v-if="link">Copia este enlace<input :value="link" readonly @focus="($event.target as HTMLInputElement).select()" /></label></div><p v-if="error" role="alert">{{error}}</p></section></template>
